// The official return type of v.size() is std::vector<int>::size_type
std::vector<int> v;

// Problem: On 64-bit Windows, unsigned is 32 bits, but size_type is 64 bits.
// This can lead to truncation and incorrect behavior with very large vectors.
unsigned sz_problem = v.size();

// Correct: 'auto' deduces the exact type: std::vector<int>::size_type.
// This code is portable and correct on all platforms.
auto sz_correct = v.size();
